async function runLogicalQueue(spec,options={}) {
 const root="C:\\workspace\\xenoamess_hoi4_dev";
 if(!/^[A-Za-z0-9_-]+$/.test(spec.runId||""))throw Error("Safe run identity required");
 const maxCalls=spec.maxCalls??192,maxBytes=spec.maxPreviewBytes??(16*1024*1024);
 if(!Number.isInteger(maxCalls)||maxCalls<1||maxCalls>192||maxBytes<8*65536||maxBytes>16*1024*1024)throw Error("Invalid logical transport bounds");
 const run=options.run||(async(cmd,budget=2500)=>{
  let r=await tools.exec_command({cmd,shell:"cmd.exe",login:false,workdir:root,max_output_tokens:budget});
  let output=r.output||"";
  while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:budget});output+=r.output||"";}
  r={...r,output};store(spec.runId+"_last_local_result",{command:cmd,result:r,observed_at_utc:new Date().toISOString()});
  if(r.exit_code!==0)throw Error(JSON.stringify(r));return r;
 });
 const sleep=options.sleep||(ms=>new Promise(resolve=>setTimeout(resolve,ms)));
 const produceWindow=options.producer||eval("("+load("bounded_window_source")+")");
 const started=Date.now();let requests=0,displayBytes=0,windows=0,wasIdle=false;
 let lastCheckpoint=started-(spec.checkpointIntervalSeconds??1800)*1000;
 await run("python tools\\rolling_production_queue.py claim "+spec.runId+" --index "+spec.startIndex+" --after "+spec.afterWindow);
 const renderResult=async({path,key,batch})=>{
  if(!/^C:\\[A-Za-z0-9_\\.\/-]+\.png$/i.test(path))throw Error("Unsafe actual PNG path; preserve result for reconciliation");
  const preview=JSON.parse((await run('python tools\\production_transport_preview.py --image '+path,40000)).output);
  if(preview.preview_bytes>65536||!preview.image_url.startsWith("data:image/png;base64,"))throw Error("Display transport budget violated");
  displayBytes+=preview.preview_bytes;
  generatedImage({image_url:preview.image_url,output_hint:preview.output_hint});
 };
 try{
  while(requests+8<=maxCalls&&displayBytes+8*65536<=maxBytes&&Date.now()-started<(spec.maxRunSeconds??21600)*1000){
   const next=JSON.parse((await run("python tools\\rolling_production_queue.py next "+spec.runId)).output);
   if(next.stop_requested)break;
   if(!next.ready){
    if(!wasIdle)notify(spec.runId+": logical queue waiting for allowed prepared/manual-reviewed HIGH work; owner retained, automatic wake, no image replay");
    wasIdle=true;await sleep(5000);continue;
   }
   wasIdle=false;
   if(!options.producer&&Date.now()-lastCheckpoint>=(spec.checkpointIntervalSeconds??1800)*1000
      &&(next.requests>=4||Date.now()-lastCheckpoint>=3600000)){
    next.plan[0].checkpointCommand="python tools\\production_checkpoint.py "+next.plan[0].batch;
    lastCheckpoint=Date.now();
   }
   await produceWindow(next.plan,{windowId:next.window_id,renderResult});
   requests+=next.requests;windows++;
   await run("python tools\\rolling_production_queue.py complete "+spec.runId);
   notify(spec.runId+": logical queue advanced automatically through window "+windows+", requests "+requests+", bounded display bytes "+displayBytes);
   await yield_control();
  }
  await run("python tools\\rolling_production_queue.py stop "+spec.runId+" --reason bounded_transport_or_run_duration");
  return {run_id:spec.runId,windows,requests,display_bytes:displayBytes,status:"safe_boundary"};
 }catch(error){
  notify(spec.runId+": logical owner retained after failure; reconcile actual ledger/prepared jobs before resuming; "+String(error));
  throw error;
 }
}

async function produceWindow(plan, options={}) {
 const root="C:\\workspace\\xenoamess_hoi4_dev";
 const windowId=options.windowId;
 if(!/^[a-zA-Z0-9_-]+$/.test(windowId||""))throw Error("An explicit safe windowId is required");
 if(!Array.isArray(plan)||!plan.length)throw Error("A nonempty prepared plan is required");
 const events=[],seen=new Set();let total=0;
 const emit=(phase,detail={})=>events.push({phase,observed_at_utc:new Date().toISOString(),...detail});
 const run=async cmd=>{
  let r=await tools.exec_command({cmd,shell:"cmd.exe",login:false,workdir:root,max_output_tokens:4000});
  while(r.session_id)r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:4000});
  if(r.exit_code!==0)throw Error(JSON.stringify(r));return r;
 };
 // Inspect the entire bounded plan before the first irreversible image dispatch.
 for(const item of plan){
  if(!/^[a-zA-Z0-9_-]+$/.test(item.batch||"")||!/^runtime[\\/][a-zA-Z0-9_\\/.-]+\.json$/.test(item.jobs||"")||item.jobs.split(/[\\/]/).includes(".."))throw Error("Unsafe batch or jobs path");
  const keys=JSON.parse((await run("python runtime\\batch-keys.py "+item.jobs)).output);
  if(!Array.isArray(keys)||!keys.length)throw Error("Empty or invalid prepared batch");
  for(const key of keys){
   if(!/^[0-9a-f]{64}$/.test(key)||seen.has(key))throw Error("Invalid or duplicate source across prepared batches");
   seen.add(key);
  }
  total+=keys.length;
  if(total>8)throw Error("Window accepts at most 8 requests in total; preserve the IPC bound");
 }
 const report={schema_version:1,machine_id:"bf-202609141645-5434332d4d",window_id:windowId,started_at_utc:new Date().toISOString(),planned_requests:total,batches:plan.map(x=>({batch:x.batch,jobs:x.jobs})),events};
 const persist=async suffix=>{
  const path=root+"\\mod_nailong\\data\\production-window-timings\\"+windowId+"-"+suffix+".json";
  await tools.apply_patch("*** Begin Patch\n*** Add File: "+path+"\n+"+JSON.stringify(report,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
 };
 await persist("started");
 try{
  const produce=options.producer||eval("("+load("bounded_produce_source")+")");
  for(const item of plan){
   emit("batch_dispatch_started",{batch:item.batch});
   await produce(item.jobs,item.batch,item.checkpointCommand||"",{onEvent:e=>events.push(e),renderResult:options.renderResult});
   emit("batch_imports_completed",{batch:item.batch});
   // The same executor advances immediately; no model/review/documentation turn here.
  }
  report.status="completed";report.completed_at_utc=new Date().toISOString();
  await persist("completed");
  notify(windowId+": bounded prepared plan completed; "+total+" requests maximum, one builtin lane");
 }catch(error){
  report.status="stopped_requires_reconciliation";report.error=String(error);report.stopped_at_utc=new Date().toISOString();
  await persist("stopped");throw error;
 }
 return report;
}

async function produce(jobFile,batch,checkpointCommand="",options={}) {
 const emit=(phase,detail={})=>options.onEvent?.({phase,batch,observed_at_utc:new Date().toISOString(),...detail});
 emit("batch_started",{jobs_file:jobFile});
 const root="C:\\workspace\\xenoamess_hoi4_dev";
 const run=async(cmd,budget=1600)=>{const start=Date.now();emit("local_command_started",{command:cmd});let r=await tools.exec_command({cmd,shell:"cmd.exe",login:false,workdir:root,max_output_tokens:budget});let output=r.output||"";while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",max_output_tokens:budget,yield_time_ms:1000});output+=r.output||"";}r={...r,output};emit("local_command_finished",{command:cmd,elapsed_ms:Date.now()-start,exit_code:r.exit_code});if(r.exit_code!==0)throw Error(JSON.stringify(r));return r;};
 const keys=JSON.parse((await run("python runtime\\batch-keys.py "+jobFile,3000)).output),todo=[...keys];
 if(keys.length>8)throw Error("Bounded cell accepts at most8 actual requests");
 let checkpoint=null,checkpointResult=null,checkpointStarted=false,checkpointFailureRecorded=false,boundaryInitialized=false;const pending=[];
 const flush=async()=>{
  if(checkpoint && !checkpointResult)return false;
  if(boundaryInitialized&&!pending.length)return true;
  while(pending.length){const item=pending[0];
   if(item.errorFile)await run("python mod_nailong\\tools\\generation_requests.py fail --key "+item.key+" --message-file "+item.errorFile);
   else await run("python mod_nailong\\tools\\generation_requests.py finish --key "+item.key+" --image "+item.path);
   pending.shift();
  }
  // Only this executor mutates canonical requests, after checkpoint/import barriers.
  const preparation=JSON.parse((await run("python tools\\production_prepare_boundary.py --apply-reviews",1600)).output);
  boundaryInitialized=true;
  if(preparation.status==="preparation_requires_reconciliation")notify(batch+": future preparation stopped for reconciliation; current prepared originals continue");
  if(checkpointResult?.error&&!checkpointFailureRecorded){
   const failure={machine_id:"bf-202609141645-5434332d4d",observed_at_utc:new Date().toISOString(),batch,jobs_file:jobFile,error:String(checkpointResult.error),status:"checkpoint_requires_reconciliation_unrelated_generation_continues",scope:"Checkpoint subprocess has exited. Actual returns/errors imported by the sole executor. No successful validation,commit,push or readback claimed for the failed checkpoint. Future checkpoint must reconcile and validate preserved task files;no image request replay or retry."};
   await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"\\mod_nailong\\data\\checkpoint-validation-failures\\"+batch+"-"+Date.now()+".json\n+"+JSON.stringify(failure,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
   checkpointFailureRecorded=true;notify(batch+": checkpoint failed and recorded separately; actual results preserved; unrelated prepared originals continue");
  }
  return true;
 };
 let deferredWithoutDispatch=0;
 while(todo.length){
  await flush();
  const key=todo.shift();
  if(pending.some(p=>p.errorFile)){
   const held=pending.filter(p=>p.errorFile).map(p=>p.key).join(',');
   const check=JSON.parse((await run("python runtime\\deferred-service-family-20261020.py "+key+" "+held,1000)).output);
   if(check.defer){todo.push(key);deferredWithoutDispatch++;notify(batch+": same-person pending service error deferred; unrelated prepared sources continue");
    if(deferredWithoutDispatch>=todo.length){await checkpoint;await flush();deferredWithoutDispatch=0;}continue;}
  }
  deferredWithoutDispatch=0;
  const j=JSON.parse((await run("python mod_nailong\\tools\\production_queue.py export-job --jobs-file "+jobFile+" --key "+key,8000)).output);
  const eligibility=JSON.parse((await run("python runtime\\guard-dispatch-family.py "+key,1600)).output);
  if(!eligibility.eligible){notify(batch+": same-person service hold preserved; no alternate request dispatched");continue;}
  const actual="runtime\\dispatch-actual\\"+batch+"-"+key+".json";
  await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"\\"+actual+"\n+"+JSON.stringify(j,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
  await run("python mod_nailong\\tools\\production_queue.py begin --actual-job-file "+actual+" --key "+key);
  notify(batch+" "+(keys.indexOf(key)+1)+"/"+keys.length+": "+j.source+"; exact payload frozen; one builtin lane");await yield_control();
  // Exact original and current raw edit target already actually viewed on SHA-bound immutable comparison pages before preparation; do not re-display duplicate inputs here.
  emit("image_invoked",{key});const imageStarted=Date.now();
  const promise=tools.image_gen__imagegen({prompt:j.prompt,referenced_image_paths:j.references,transparent_background:j.transparent}).then(r=>({r}),e=>({error:String(e)}));
  if(checkpointCommand&&!checkpointStarted){checkpointStarted=true;checkpoint=run(checkpointCommand,2500).then(r=>{checkpointResult={r};return checkpointResult;},e=>{checkpointResult={error:String(e)};return checkpointResult;});}
  const outcome=await promise;
  emit("image_resolved",{key,elapsed_ms:Date.now()-imageStarted,error:outcome.error??null});
  if(outcome.error){
   const file="runtime\\"+batch+"-error-"+key+".txt";
   await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"\\"+file+"\n+"+outcome.error.replaceAll("\n","\n+")+"\n*** End Patch");
   await run("python mod_nailong\\tools\\production_queue.py returned --key "+key+" --error-file "+file);
   pending.push({key,errorFile:file});
   notify(batch+": actual error durably recorded; no immediate retry");
   if(!outcome.error.includes("moderation_blocked")){if(checkpoint)await checkpoint;await flush();throw Error(outcome.error);}
  }else{
   const path=outcome.r.output_hint?.match(/ as (C:\\[^\n]+?\.png) by default\./)?.[1];
   if(!path){store(batch+"_unparsed_"+key,outcome.r);throw Error("Actual result retained; inspect without another call");}
   await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"\\runtime\\"+batch+"-result-"+key+".json\n+"+JSON.stringify({path,output_hint:outcome.r.output_hint},null,2).replaceAll("\n","\n+")+"\n*** End Patch");
   await run("python mod_nailong\\tools\\production_queue.py returned --key "+key+" --image "+path);
   pending.push({key,path});
   if(options.renderResult)await options.renderResult({result:outcome.r,path,key,batch});
   else generatedImage(outcome.r);
  }
  await flush();
 }
 if(checkpoint)await checkpoint;
 await flush();
 if(checkpointCommand&&!checkpointStarted)await run(checkpointCommand,2500);
 emit("batch_completed");
 notify(batch+" actual distinct requests finished; all returns/errors imported; no image call replayed");
}

